Bool IsPrime(I64 n)
{
  I64 d;
  if (n < 2) return FALSE;
  for (d = 2; d * d <= n; d++)
    if (n % d == 0) return FALSE;
  return TRUE;
}

I64 n;
for (n = 2; n <= 50; n++)
  if (IsPrime(n))
    "%d ", n;
"\n";

I64 Fib(I64 n)
{
  if (n < 2) return n;
  return Fib(n - 1) + Fib(n - 2);
}

